for (int i = (size / 2) - 1; i >= 0; i--) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < size && arr[left] < arr[smallest]) {
        smallest = left;
    }

    if (right < size && arr[right] < arr[smallest]) {
        smallest = right;
    }

    if (smallest != i) {
        std::swap(arr[i], arr[smallest]);
        int parent = smallest;

        while (true) {
            int newSmallest = parent;
            int leftChild = 2 * parent + 1;
            int rightChild = 2 * parent + 2;

            if (leftChild < size && arr[leftChild] < arr[newSmallest]) {
                newSmallest = leftChild;
            }

            if (rightChild < size && arr[rightChild] < arr[newSmallest]) {
                newSmallest = rightChild;
            }

            if (newSmallest == parent) {
                break;
            }

            std::swap(arr[parent], arr[newSmallest]);
            parent = newSmallest;
        }
    }
}
